<?php namespace App\Http\Controllers\Api; use App\Http\Controllers\Api\Concerns\HandlesDomainModules; use App\Http\Controllers\Controller; use App\Http\Requests\B2BModuleRequest; use Illuminate\Http\JsonResponse; class B2BModuleController extends Controller { use HandlesDomainModules; protected function domain(): string { return 'b2b'; } public function store(B2BModuleRequest $request, string $module): JsonResponse { $this->registry->assertDomain($this->domain(), $module); return response()->json($this->service->create($request, $module, $request->validated()), 201); } public function update(B2BModuleRequest $request, string $module, int $id): JsonResponse { $this->registry->assertDomain($this->domain(), $module); return response()->json($this->service->update($request, $module, $id, $request->validated())); } }
